const fs = require('fs');
const path = require('path');
const DEFECTS_FILE = path.join(__dirname, '..', 'state', 'defects.json');

function listDefects() {
  return JSON.parse(fs.readFileSync(DEFECTS_FILE, 'utf8'));
}

function spawnDefectRecord(unitId, cause) {
  const list = listDefects();
  const entry = { defectId: 'def-' + (100 + list.length), unitId, cause };
  list.push(entry);
  fs.writeFileSync(DEFECTS_FILE, JSON.stringify(list, null, 2) + '\n');
  return entry;
}

module.exports = { listDefects, spawnDefectRecord, DEFECTS_FILE };

